package com.alpharip.staffmod.IncidentPostMortemBoard; public final class IncidentAssignment { private String assignee,assignedBy; private long assignedAt; public IncidentAssignment(){} public IncidentAssignment(String a,String b,long t){if(a==null||a.trim().isEmpty())throw new IllegalArgumentException("Assignee required");assignee=a.trim();assignedBy=b==null?"":b.trim();if(t<=0)throw new IllegalArgumentException("Timestamp must be positive");assignedAt=t;} public String getAssignee(){return assignee;} public String getAssignedBy(){return assignedBy;} public long getAssignedAt(){return assignedAt;} }